def solve(n: int) -> str:
    result = []
    while n > 0:
        n -= 1
        result.append(chr(ord('A') + n % 26))
        n //= 26
    return ''.join(reversed(result))

def solve(num: int, den: int) -> int:
    quotient, remainder = divmod(abs(num), den)
    if 2 * remainder >= den:
        quotient += 1
    return quotient if num >= 0 else -quotient

def solve(a: int, b: int) -> list:
    q = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        q = -q
    return [q, a - b * q]

def solve(coins: list, amount: int) -> int:
    dp = [0] + [amount + 1] * amount
    for value in coins:
        for total in range(value, amount + 1):
            dp[total] = min(dp[total], dp[total - value] + 1)
    return dp[amount] if dp[amount] <= amount else -1

def solve(n: int) -> str:
    ones = [
        "zero", "one", "two", "three", "four", "five", "six", "seven",
        "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen",
        "fifteen", "sixteen", "seventeen", "eighteen", "nineteen",
    ]
    tens = [
        "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy",
        "eighty", "ninety",
    ]

    def under_thousand(value: int) -> str:
        parts = []
        hundreds, remainder = divmod(value, 100)

        if hundreds:
            parts.append(ones[hundreds] + " hundred")
            if remainder:
                parts.append("and")

        if remainder >= 20:
            ten, unit = divmod(remainder, 10)
            parts.append(tens[ten] + ("-" + ones[unit] if unit else ""))
        elif remainder:
            parts.append(ones[remainder])

        return " ".join(parts)

    if n < 1000:
        return under_thousand(n)

    thousands, remainder = divmod(n, 1000)
    result = ones[thousands] + " thousand"

    if remainder:
        connector = " and " if remainder < 100 else " "
        result += connector + under_thousand(remainder)

    return result

def solve(a: str, b: str) -> int:
    def compare_numbers(left: str, right: str) -> int:
        left = left.lstrip("0") or "0"
        right = right.lstrip("0") or "0"
        if len(left) != len(right):
            return 1 if len(left) > len(right) else -1
        return (left > right) - (left < right)

    def parse(version: str):
        core, separator, prerelease = version.partition("-")
        return core.split("."), prerelease.split(".") if separator else None

    core_a, pre_a = parse(a)
    core_b, pre_b = parse(b)

    for left, right in zip(core_a, core_b):
        result = compare_numbers(left, right)
        if result:
            return result

    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        return 1
    if pre_b is None:
        return -1

    for left, right in zip(pre_a, pre_b):
        left_numeric = left.isascii() and left.isdigit()
        right_numeric = right.isascii() and right.isdigit()

        if left_numeric and right_numeric:
            result = compare_numbers(left, right)
        elif left_numeric != right_numeric:
            result = -1 if left_numeric else 1
        else:
            result = (left > right) - (left < right)

        if result:
            return result

    return (len(pre_a) > len(pre_b)) - (len(pre_a) < len(pre_b))

def solve(expression: str) -> int:
    position = 0

    def skip_spaces():
        nonlocal position
        while position < len(expression) and expression[position].isspace():
            position += 1

    def parse_factor(allow_negation):
        nonlocal position
        skip_spaces()
        negative = False
        if allow_negation and position < len(expression) and expression[position] == "-":
            negative = True
            position += 1
            skip_spaces()

        if position < len(expression) and expression[position] == "(":
            position += 1
            value = parse_expression(True)
            skip_spaces()
            position += 1
        else:
            start = position
            while position < len(expression) and expression[position].isdigit():
                position += 1
            value = int(expression[start:position])

        return -value if negative else value

    def parse_term(allow_negation):
        nonlocal position
        value = parse_factor(allow_negation)

        while True:
            skip_spaces()
            if position >= len(expression) or expression[position] not in "*/":
                return value

            operator = expression[position]
            position += 1
            right = parse_factor(False)

            if operator == "*":
                value *= right
            else:
                quotient = abs(value) // abs(right)
                value = -quotient if (value < 0) != (right < 0) else quotient

    def parse_expression(allow_negation):
        nonlocal position
        value = parse_term(allow_negation)

        while True:
            skip_spaces()
            if position >= len(expression) or expression[position] not in "+-":
                return value

            operator = expression[position]
            position += 1
            right = parse_term(False)
            value = value + right if operator == "+" else value - right

    return parse_expression(True)

def solve(line: str) -> list:
    fields = []
    i = 0
    n = len(line)

    while True:
        if i < n and line[i] == '"':
            i += 1
            chars = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        chars.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    chars.append(line[i])
                    i += 1
            field = "".join(chars)
        else:
            start = i
            while i < n and line[i] != ',':
                i += 1
            field = line[start:i]

        fields.append(field)

        if i >= n:
            break
        i += 1
        if i == n:
            fields.append("")
            break

    return fields

def solve(s: str) -> str:
    words = s.lower().split(" ")
    nonempty = [i for i, word in enumerate(words) if word]
    if not nonempty:
        return " ".join(words)

    stop_words = {"a", "an", "and", "the", "of", "in", "on", "to", "for"}
    first, last = nonempty[0], nonempty[-1]

    for i, word in enumerate(words):
        if word and (word not in stop_words or i == first or i == last):
            words[i] = word[0].upper() + word[1:]

    return " ".join(words)

def solve(s: str) -> list:
    if not s:
        return []

    words = []
    start = 0

    for i in range(1, len(s)):
        boundary = (
            s[i].isupper()
            and (s[i - 1].islower() or s[i - 1].isdigit())
        ) or (
            s[i - 1].isupper()
            and s[i].isupper()
            and i + 1 < len(s)
            and s[i + 1].islower()
        )

        if boundary:
            words.append(s[start:i])
            start = i

    words.append(s[start:])
    return words

def solve(matrix: list) -> list:
    if not matrix or not matrix[0]:
        return []

    result = []
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1

    while top <= bottom and left <= right:
        for col in range(left, right + 1):
            result.append(matrix[top][col])
        top += 1

        for row in range(top, bottom + 1):
            result.append(matrix[row][right])
        right -= 1

        if top <= bottom:
            for col in range(right, left - 1, -1):
                result.append(matrix[bottom][col])
            bottom -= 1

        if left <= right:
            for row in range(bottom, top - 1, -1):
                result.append(matrix[row][left])
            left += 1

    return result

def solve(nums: list) -> list:
    result = list(nums)
    pivot = len(result) - 2

    while pivot >= 0 and result[pivot] >= result[pivot + 1]:
        pivot -= 1

    if pivot < 0:
        return sorted(result)

    successor = len(result) - 1
    while result[successor] <= result[pivot]:
        successor -= 1

    result[pivot], result[successor] = result[successor], result[pivot]
    result[pivot + 1:] = reversed(result[pivot + 1:])
    return result

def solve(y1: int, m1: int, d1: int, y2: int, m2: int, d2: int) -> int:
    def ordinal(year: int, month: int, day: int) -> int:
        prior_year = year - 1
        total = 365 * prior_year + prior_year // 4 - prior_year // 100 + prior_year // 400
        month_days = (0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334)
        total += month_days[month - 1]
        if month > 2 and (year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)):
            total += 1
        return total + day

    return ordinal(y2, m2, d2) - ordinal(y1, m1, d1)

def solve(seconds: int) -> str:
    if seconds == 0:
        return "now"

    parts = []
    for unit, size in (("day", 86400), ("hour", 3600), ("minute", 60), ("second", 1)):
        amount, seconds = divmod(seconds, size)
        if amount:
            name = unit if amount == 1 else unit + "s"
            parts.append(f"{amount} {name}")

    if len(parts) == 1:
        return parts[0]
    return ", ".join(parts[:-1]) + " and " + parts[-1]

def solve(s: str) -> bool:
    parts = s.split(".")
    if len(parts) != 4:
        return False

    for part in parts:
        if not part or any(char < "0" or char > "9" for char in part):
            return False
        if len(part) > 1 and part[0] == "0":
            return False
        if int(part) > 255:
            return False

    return True

def solve(s: str) -> bool:
    digits = []
    for ch in s:
        if ch == " ":
            continue
        if not ("0" <= ch <= "9"):
            return False
        digits.append(int(ch))

    if len(digits) < 2:
        return False

    total = 0
    for i, digit in enumerate(reversed(digits)):
        if i % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit

    return total % 10 == 0

import re

def solve(items: list) -> list:
    def sort_key(item):
        runs = re.findall(r"[0-9]+|[^0-9]+", item)
        return tuple(
            (0, int(run)) if run[0].isdigit() and run[0].isascii()
            else (1, run.casefold())
            for run in runs
        )

    return sorted(items, key=sort_key)

def solve(text: str, width: int) -> list:
    words = text.split()
    lines = []
    line = ""

    for word in words:
        candidate = word if not line else line + " " + word
        if line and len(candidate) > width:
            lines.append(line)
            line = word
        else:
            line = candidate

    if line:
        lines.append(line)

    return lines

def solve(digits: str, b1: int, b2: int) -> str:
    alphabet = "0123456789abcdefghijklmnopqrstuvwxyz"
    value = 0
    for digit in digits:
        value = value * b1 + alphabet.index(digit)

    if value == 0:
        return "0"

    result = []
    while value:
        value, remainder = divmod(value, b2)
        result.append(alphabet[remainder])
    return "".join(reversed(result))
